"""Explain the distribution-level result that makes Flow Matching useful."""
from common import *
import fm_figures as figures


def build():
    data=figures.simulation()
    body='<script src="assets/fm.js?v=3" defer></script>'
    body+=sec('purpose','何ができれば「生成できた」と言えるのか',
        p('手書き数字を学習したなら、新しいノイズから手書き数字らしい画像を作りたい。しかも同じ数字ばかりではなく、訓練データにある多様さも再現したい。生成モデルが合わせたいのは、<strong>一つの決まった正解との対応ではなく、生成したデータの集まり方＝分布</strong>です。画像なら1点は画素値を全部並べた1枚ぶんのベクトル、またはその潜在表現です。')+
        p('このページでは、画像の代わりに<strong>「中央の丸い点群から、斜めに離れた二つの山を作る」</strong>という2次元の問題を使います。出発時にはどちらの山へ行くかをラベルで渡しません。動かした結果として、両方の山に点が集まる必要があります。')+
        figures.destination(data)+
        p('<a href="normalizing-flow.html#invertible">Normalizing Flow</a>では、可逆な演算を重ねて分布を変えました。連続時間のFlowでは、現在の位置と時刻から速度を出すネットワークを使い、小さな移動の積み重ねで分布を変えます。では、目的の分布へ動かす速度を、どうやって学べばよいでしょうか。')+
        p('<strong>Flow Matchingの工夫は、データ全体を動かす正しい速度を先に求めなくても、個々のノイズとデータから作れる速度だけで、それに相当する学習ができることです。</strong>連続時間Flowを尤度で学習する際の重いODE計算を学習ループから外せること、拡散過程に限らず経路を選べることが、提案の動機です。生成時の反復計算は必要です。'))
    body+=sec('targets','一本の直線は簡単。でも、全部を同時に再現することはできない',
        p('ノイズx₀を一つ、データx₁を一つ独立に選び、直線で結ぶとします。両端を知っていれば、途中の位置も速度も計算は簡単です。')+
        eq(r'x_t=(1-t)x_0+tx_1,\qquad u=x_1-x_0','ここではt=0がノイズ、t=1がデータ。uは選んだ1ペアについての速度です。直線はFlow Matchingで使える経路の一例です。')+
        p('しかし、これを何万組も作ると事情が変わります。近いノイズでも、一方は左の山、もう一方は右の山のデータと組になるかもしれません。途中の近い場所に、逆向きに進むペアが混ざります。<strong>ネットワークが見るのは途中の位置xと時刻tだけで、その点がどのペアだったかも、行き先x₁も見えません。</strong>')+
        figures.crossings(data)+
        p('つまり「指定された終点へ直進する関数」を覚える問題にはできません。同じ位置・時刻に異なる目標速度があり得るのに、一つのネットワークは一つの速度を出すからです。ここで個々の直線を再現しようとせず、<strong>その位置・時刻に来る経路の速度を平均する</strong>ことを考えます。'))
    body+=sec('training','どの平均を学ぶのか：全部のデータを平均するわけではない',
        p('二乗誤差で速度を学習すると、理想的な予測は「この位置・時刻に来た」という条件のもとでの平均速度になります。左右の山が半分ずつあるからといって、どこでも半分ずつ混ぜるわけではありません。時刻が進んで右の山の近くにいるなら、そこを通るのは右の山へ向かう経路が多くなります。')+
        figures.average()+
        eq(r'v^*(x,t)=\mathbb E[x_1-x_0\mid x_t=x]', 'v*は理想的に学べた場合の速度。「今いる場所と時刻」を固定して、その場所に来るペアの速度を平均します。実際のネットワークはこれを近似します。')+
        p('この平均を全データについて直接計算するのは、画像のような高次元では大変です。そこで学習時には、ランダムに選んだ1ペアの速度を目標にします。多数のペアで次の損失を下げれば、平均速度を明示的に計算せずに、それを予測する学習になります。')+
        eq(r'L_{\mathrm{CFM}}=\mathbb E_{x_0,x_1,t}\left[\|v_\theta(x_t,t)-(x_1-x_0)\|^2\right]', '入力はxₜとt、目標はそのペアのx₁−x₀。ペアごとの目標が食い違うため、完全に学べてもこの損失が0になるとは限りません。')+
        note('単なる「教師あり回帰」との違いは、目標をどう作り、その平均に何が保証されるか', '回帰の仕組み自体は同じです。Flow Matchingで重要なのは、個別の経路から作った目標で学習すると、分布全体を動かす速度の学習になるという対応です。一定の条件のもとで、ペアの速度を目標にした損失と、理想の平均速度を目標にした損失は、重みに依存しない定数だけ異なります。したがって重みの更新方向が一致します。'))
    body+=sec('why-average','速度を平均しても、なぜ二つの山が残るのか',
        p('「平均したら真ん中に集まってしまうのでは？」という疑問が出ます。平均するのは完成データ全体でも、全場所の速度でもなく、<strong>ある時刻の、ある場所を通る速度</strong>です。位置が変われば、混ざる経路の割合も変わり、予測する速度も変わります。左右で違う速度が生まれるため、二つの山を作れます。')+
        p('さらに、この平均には分布を保つ理由があります。小さな領域を考えると、点の数が増減するのは、周りから入ってくる量と外へ出ていく量の差で決まります。経路ごとの速度を、その場所にいる割合で平均すれば、<strong>その場所での「点の密度×平均速度」は、元の各経路の流れを合計したものと同じ</strong>です。したがって個々の点の道筋が変わっても、密度の変化は同じになります。これは連続の式で表せます。')+
        eq(r'\partial_t p_t(x)=-\nabla\!\cdot\!\bigl(p_t(x)v^*(x,t)\bigr)', '左はその場所の密度の変化、右は出入りする流れの差。適切な正則性と初期分布のもとで、平均速度のODEは、元の直線ペア群と同じ時刻ごとの分布を作ります。')+
        p('この例の対称な中心では速度が0になることがあります。ただし、連続分布から厳密にその中心の点を引く確率は0です。「全点が同じ中心へ止まる」という意味にはなりません。下の図で、中心の一つの例ではなく、点群全体がどう動くかを確認してください。'))
    body+=sec('sampling','直線の寄せ集めと、実際に生成する流れを見比べる',
        p('左は、ノイズとデータのペアを結んだ学習用の直線です。右は、同じノイズから出発して、その位置での平均速度だけで進んだ生成の経路です。右の点には行き先を渡していません。<strong>赤点の行き先は左右で違うのに、全体はどちらも二つの山になる</strong>ことに注目してください。')+
        figures.transport(data)+
        p('生成では、現在の位置と時刻を速度ネットワークへ入力し、予測した速度で少し進み、移動先で速度を計算し直します。同じ時刻・位置には一つの速度が決まるので、十分滑らかな速度場の生成軌道は同時刻に交差しません。学習用のランダムな直線とは、個々の対応が違うのです。')+
        eq(r'\frac{\mathrm dx}{\mathrm dt}=v_\theta(x,t),\qquad x_{t+\Delta t}\approx x_t+\Delta t\,v_\theta(x_t,t)', '右は最も単純なEuler法の1歩。上の図はより精度の高いRK4法で計算しています。どちらも、生成時には未知のx₁を使いません。')+
        p('この図は仕組みを検証できるよう、正しい平均速度を数式から計算できる例です。実データではその式を知らないため、ネットワークに学習させます。ネットワークの近似誤差や数値積分の誤差が大きければ、狙った分布からずれます。直線の学習目標を使ったからといって、生成が一歩で終わる保証もありません。'))
    body+=sec('compare','Normalizing Flow・Diffusionとは何が違う？',
        table(['方法','分布をどう変えるか／何を学ぶか'],[
            ('離散Normalizing Flow','密度の伸縮を計算しやすい可逆層を重ね、通常は尤度で学ぶ。'),
            ('Continuous Normalizing Flow','速度のODEで分布を連続的に変えるモデル。Flow Matchingは、その速度を学ぶ方法の一つ。'),
            ('Diffusion（DDPMの例）','決めたノイズ付加過程の途中からノイズなどを予測して学び、対応するサンプラで生成する。'),
            ('Flow Matching','選んだ確率経路の速度を学ぶ。個々の経路から作った速度で、全体の速度を学習できる。拡散型の経路も、ここで使った直線型の経路も扱える。')])+
        p('この例でノイズとデータを独立に組にしたことは、分布全体で最短の対応を求めたことを意味しません。ペアの組み方や経路の選び方は、目標速度のばらつきや生成経路の曲がり方、必要な計算回数に影響します。そこも手法の設計対象です。'))
    body+=refs([('Flow Matching原論文：§3.1の分布と平均速度、§3.2の学習目的の等価性','https://arxiv.org/html/2210.02747v2'),('Rectified Flow：直線ペアの速度回帰と生成の関係','https://arxiv.org/abs/2209.03003')])
    page('flow-matching','Flow Matching — 個々の経路から、分布の動かし方を学ぶ','モデルの構造','MODEL 10 / FLOW MATCHING','バラバラに結んだ直線の速度から、なぜ新しいデータを生成できるのか。二つの山を作る一つの例で確かめます。',body)
